    import React from "react";
import { Outlet, Link, useNavigate, useLocation } from "react-router-dom";
import {
  FaBookOpen,
  FaChalkboardTeacher,
  FaUserGraduate,
  FaCalendarAlt,
  FaSignOutAlt,
  FaGraduationCap
} from "react-icons/fa";

function MainLayout() {
  const navigate = useNavigate();
  const location = useLocation();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  const linkStyle = (path) => ({
    display: "flex",
    alignItems: "center",
    gap: "10px",
    padding: "12px 14px",
    borderRadius: "12px",
    textDecoration: "none",
    color: location.pathname === path ? "#fff" : "#333",
    background: location.pathname === path ? "#7b1fa2" : "transparent",
    fontWeight: "600",
    marginBottom: "10px"
  });

  return (
    <div
      style={{
        display: "flex",
        minHeight: "100vh",
        background: "#f5f7fb"
      }}
    >
      <aside
        style={{
          width: "250px",
          background: "#fff",
          padding: "20px",
          boxShadow: "2px 0 12px rgba(0,0,0,0.06)"
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "22px",
            fontWeight: "bold",
            color: "#7b1fa2",
            marginBottom: "30px"
          }}
        >
          <FaGraduationCap />
          LMS
        </div>

        {role === "teacher" && (
          <Link to="/teacher-dashboard" style={linkStyle("/teacher-dashboard")}>
            <FaChalkboardTeacher />
            Teacher Dashboard
          </Link>
        )}

        {role === "student" && (
          <Link to="/student-dashboard" style={linkStyle("/student-dashboard")}>
            <FaUserGraduate />
            Student Dashboard
          </Link>
        )}

        <Link to="/courses" style={linkStyle("/courses")}>
          <FaBookOpen />
          Courses
        </Link>

        {role === "student" && (
          <Link to="/planner" style={linkStyle("/planner")}>
            <FaCalendarAlt />
            Planner
          </Link>
        )}

        <button
          onClick={handleLogout}
          style={{
            marginTop: "20px",
            width: "100%",
            border: "none",
            background: "#e53935",
            color: "#fff",
            padding: "12px",
            borderRadius: "12px",
            fontWeight: "bold",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: "10px"
          }}
        >
          <FaSignOutAlt />
          Logout
        </button>
      </aside>

      <main style={{ flex: 1, padding: "25px" }}>
        <div
          style={{
            background: "linear-gradient(135deg, #7b1fa2, #512da8)",
            color: "#fff",
            borderRadius: "18px",
            padding: "22px",
            marginBottom: "25px",
            boxShadow: "0 8px 24px rgba(123,31,162,0.25)"
          }}
        >
          <h2 style={{ margin: 0 }}>Welcome, {userName}</h2>
          <p style={{ marginTop: "8px", opacity: 0.9 }}>
            {role === "teacher"
              ? "Manage your courses and track your teaching content."
              : "Track your courses, planner, and learning progress."}
          </p>
        </div>

        <Outlet />
      </main>
    </div>
  );
}

export default MainLayout;
